// Oracle stub for the pi-tui `Markdown` renderer (ported by the M4 TUI slice,
// not linked here). The self-update note path falls back to plain text when
// rendering throws; the harness stub renders a fixed marker line instead.
export class Markdown {
	constructor(text, _pad, _width, _theme) {
		this.text = text;
	}
	render(_width) {
		return this.text.split("\n");
	}
}
